import java.util.function.Supplier;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLine_GetParsedOptionValueTest {

    private CommandLine cmd;

    @BeforeEach
    public void setUp() throws Exception {
        // Use reflection to invoke the private constructor CommandLine(List, List, Consumer)
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);
        List<String> args = new LinkedList<>();
        List<?> options = new ArrayList<>();
        // pass null for deprecatedHandler (allowed because we pass null reflectively)
        cmd = ctor.newInstance(args, options, null);
    }

    @Test
    public void testPublicGetParsedOptionValue_returnsNullWhenNoSelection() throws Exception {
        OptionGroup group = new OptionGroup(); // no selected option
        // call the public one-arg method which delegates to the two-arg method with a supplier that returns null
        Method publicMethod = CommandLine.class.getMethod("getParsedOptionValue", OptionGroup.class);
        Object result = publicMethod.invoke(cmd, group);
        assertNull(result, "Expected null when OptionGroup has no selection and default supplier returns null");
    }

    @Test
    public void testPrivateGetParsedOptionValue_withSupplierReturnsValue() throws Exception {
        OptionGroup group = new OptionGroup(); // no selected option

        // Find the private two-arg method: getParsedOptionValue(OptionGroup, Supplier)
        Method privateMethod = CommandLine.class.getDeclaredMethod("getParsedOptionValue", OptionGroup.class, Supplier.class);
        privateMethod.setAccessible(true);

        Supplier<String> supplier = () -> "supplied-value";
        Object result = privateMethod.invoke(cmd, group, supplier);

        assertEquals("supplied-value", result, "Expected the value returned from the provided Supplier");
    }
}

